python3 -c "
import re
with open('app/models.py') as f:
    content = f.read()
# Find all DateTime(timezone=True) columns with their table context
lines = content.splitlines()
current_table = None
results = []
for i, line in enumerate(lines):
    if 'class ' in line and '(Base)' in line:
        # Extract table name from __tablename__
        for j in range(i, min(i+5, len(lines))):
            m = re.search(r'__tablename__\s*=\s*[\"\'](.*?)[\"\']', lines[j])
            if m:
                current_table = m.group(1)
                break
    if 'DateTime(timezone=True)' in line and current_table:
        m = re.search(r'(\w+)\s*:', lines[i-1] if i > 0 else '')
        if m:
            results.append(f'    ({repr(current_table)}, {repr(m.group(1))}),')
for r in results:
    print(r)
"
